import React, { useState } from 'react';
import './sunsetPredictor.css';

const SunsetPredictor = () => {
  const [weatherData, setWeatherData] = useState({
    cloud_cover: 35,
    humidity: 65,
    wind_speed: 8,
    visibility: 12,
    temperature: 75,
    pressure: 1013,
  });

  const [prediction, setPrediction] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setWeatherData(prev => ({
      ...prev,
      [name]: parseFloat(value) || 0
    }));
  };

  // Predict sunset
  const handlePredict = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('http://localhost:5000/api/predict', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(weatherData),
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json();
      setPrediction(data);
    } catch (err) {
      setError(`Failed to predict: ${err.message}`);
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // Generate sunset colors based on hue/saturation/brightness
  const generateSunsetGradient = (hue, saturation, brightness) => {
    if (!hue && hue !== 0) return 'linear-gradient(180deg, #1a1a2e 0%, #0f3460 100%)';

    // Convert HSB to RGB
    const h = hue / 360;
    const s = Math.min(saturation, 1);
    const b = Math.min(brightness, 1);

    const c = b * s;
    const x = c * (1 - Math.abs((h * 6) % 2 - 1));
    const m = b - c;

    let r, g, bl;
    if (h < 1/6) {
      [r, g, bl] = [c, x, 0];
    } else if (h < 2/6) {
      [r, g, bl] = [x, c, 0];
    } else if (h < 3/6) {
      [r, g, bl] = [0, c, x];
    } else if (h < 4/6) {
      [r, g, bl] = [0, x, c];
    } else if (h < 5/6) {
      [r, g, bl] = [x, 0, c];
    } else {
      [r, g, bl] = [c, 0, x];
    }

    const toHex = (n) => {
      const hex = Math.round((n + m) * 255).toString(16);
      return hex.length === 1 ? '0' + hex : hex;
    };

    const topColor = `#${toHex(r)}${toHex(g)}${toHex(bl)}`;
    const bottomColor = '#1a0f2e';

    return `linear-gradient(180deg, ${topColor} 0%, ${bottomColor} 100%)`;
  };

  return (
    <div className="sunset-predictor">
      {/* Hero: Sunset Visualization */}
      <section className="hero">
        {prediction ? (
          <div 
            className="sunset-display"
            style={{
              background: generateSunsetGradient(
                prediction.hue_shift,
                prediction.saturation,
                prediction.brightness
              )
            }}
          >
            <div className="sunset-info">
              <h2>Your Predicted Sunset</h2>
              <div className="color-metrics">
                <div className="metric">
                  <span className="label">Hue</span>
                  <span className="value">{Math.round(prediction.hue_shift)}°</span>
                </div>
                <div className="metric">
                  <span className="label">Saturation</span>
                  <span className="value">{(prediction.saturation * 100).toFixed(0)}%</span>
                </div>
                <div className="metric">
                  <span className="label">Brightness</span>
                  <span className="value">{(prediction.brightness * 100).toFixed(0)}%</span>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="hero-placeholder">
            <h1>Sunset Predictor</h1>
            <p>Predict what the sunset will look like based on weather</p>
          </div>
        )}
      </section>

      {/* Main content */}
      <section className="content">
        {/* Input Form */}
        <div className="input-section">
          <h2>Weather Conditions</h2>
          <form onSubmit={handlePredict}>
            <div className="form-grid">
              <div className="form-group">
                <label htmlFor="cloud_cover">Cloud Cover (%)</label>
                <input
                  type="range"
                  id="cloud_cover"
                  name="cloud_cover"
                  min="0"
                  max="100"
                  value={weatherData.cloud_cover}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.cloud_cover}%</span>
              </div>

              <div className="form-group">
                <label htmlFor="humidity">Humidity (%)</label>
                <input
                  type="range"
                  id="humidity"
                  name="humidity"
                  min="0"
                  max="100"
                  value={weatherData.humidity}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.humidity}%</span>
              </div>

              <div className="form-group">
                <label htmlFor="wind_speed">Wind Speed (mph)</label>
                <input
                  type="range"
                  id="wind_speed"
                  name="wind_speed"
                  min="0"
                  max="30"
                  value={weatherData.wind_speed}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.wind_speed} mph</span>
              </div>

              <div className="form-group">
                <label htmlFor="visibility">Visibility (km)</label>
                <input
                  type="range"
                  id="visibility"
                  name="visibility"
                  min="1"
                  max="20"
                  step="0.5"
                  value={weatherData.visibility}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.visibility} km</span>
              </div>

              <div className="form-group">
                <label htmlFor="temperature">Temperature (°F)</label>
                <input
                  type="range"
                  id="temperature"
                  name="temperature"
                  min="30"
                  max="120"
                  value={weatherData.temperature}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.temperature}°F</span>
              </div>

              <div className="form-group">
                <label htmlFor="pressure">Pressure (mb)</label>
                <input
                  type="range"
                  id="pressure"
                  name="pressure"
                  min="980"
                  max="1050"
                  value={weatherData.pressure}
                  onChange={handleInputChange}
                  className="slider"
                />
                <span className="value-display">{weatherData.pressure} mb</span>
              </div>
            </div>

            <button 
              type="submit" 
              className="predict-button"
              disabled={loading}
            >
              {loading ? 'Predicting...' : 'Predict Sunset'}
            </button>
          </form>
        </div>

        {/* Results */}
        {error && (
          <div className="error-message">
            {error}
          </div>
        )}

        {prediction && (
          <div className="results-section">
            <h2>Sunset Details</h2>

            <div className="prediction-grid">
              <div className="prediction-card">
                <h3>Visual Characteristics</h3>
                <div className="prediction-details">
                  <div className="detail-row">
                    <span className="label">Primary Color Hue</span>
                    <span className="value">{Math.round(prediction.hue_shift)}° on the color wheel</span>
                  </div>
                  <div className="detail-row">
                    <span className="label">Color Vividness</span>
                    <span className="value">{(prediction.saturation * 100).toFixed(1)}%</span>
                  </div>
                  <div className="detail-row">
                    <span className="label">Luminosity</span>
                    <span className="value">{(prediction.brightness * 100).toFixed(1)}%</span>
                  </div>
                  <div className="detail-row">
                    <span className="label">Cloud Coverage</span>
                    <span className="value">{(prediction.cloud_density * 100).toFixed(1)}%</span>
                  </div>
                </div>
              </div>

              <div className="prediction-card">
                <h3>Sunset Description</h3>
                <p className="prompt-text">
                  {prediction.prompt}
                </p>
              </div>
            </div>

            <div className="interpretation">
              <h3>What This Means</h3>
              <div className="interpretation-text">
                {prediction.hue_shift < 50 ? (
                  <p>🔴 <strong>Red-Orange Sunset:</strong> Expect a vibrant, warm display with deep reds and oranges dominating the sky.</p>
                ) : prediction.hue_shift < 100 ? (
                  <p>🟡 <strong>Golden Sunset:</strong> The classic beautiful sunset with golden yellows and warm tones.</p>
                ) : prediction.hue_shift < 150 ? (
                  <p>🟢 <strong>Green-Tinted Sunset:</strong> Unusual atmospheric conditions creating green and cyan hues.</p>
                ) : (
                  <p>🔵 <strong>Blue-Violet Sunset:</strong> Rare purple and blue tones indicating special atmospheric conditions.</p>
                )}

                {prediction.saturation > 0.8 && (
                  <p>✨ <strong>Highly Saturated:</strong> The colors will be vivid and extremely photogenic.</p>
                )}

                {prediction.cloud_density > 0.6 && (
                  <p>☁️ <strong>Significant Cloud Cover:</strong> Clouds will diffuse the light, creating dramatic patterns and textures.</p>
                )}
              </div>
            </div>
          </div>
        )}
      </section>
    </div>
  );
};

export default SunsetPredictor;
